window.TL = {"duration": 479.43, "scenes": [{"id": "s1", "label": "Opening & Key Takeaway", "start": 0, "end": 45.64}, {"id": "s2", "label": "01. Korean Workbook Market and Competitive Landscape", "start": 45.64, "end": 116.71}, {"id": "s3", "label": "02. JEI's Strengths and Current Limitations", "start": 116.71, "end": 187.27}, {"id": "s4", "label": "03. Parents' Needs and Primary Target Customers", "start": 187.27, "end": 256.3}, {"id": "s5", "label": "04. Core Differentiation: From Assessment to Visible Growth", "start": 256.3, "end": 316.72}, {"id": "s6", "label": "05. Proposed Brand Positioning and Customer Messaging", "start": 316.72, "end": 396.02}, {"id": "s7", "label": "06. Service Development and Operational Directions", "start": 396.02, "end": 453.4}, {"id": "s8", "label": "Closing", "start": 453.4, "end": 479.43}], "cont": ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"], "order": ["title", "l1_1", "l1_2", "l1_3", "l1_4", "l1_5", "h2", "l2_1", "l2_2", "l2_3", "l2_4", "l2_5", "l2_6", "l2_7", "l2_8", "l2_9", "h3", "l3_1", "l3_2", "l3_3", "l3_4", "l3_5", "l3_6", "l3_7", "l3_8", "l3_9", "h4", "l4_1", "l4_2", "l4_3", "l4_4", "l4_5", "l4_6", "l4_7", "l4_8", "l4_9", "h5", "l5_1", "l5_2", "l5_3", "l5_4", "l5_5", "l5_6", "l5_7", "l5_8", "l5_9", "h6", "l6_1", "l6_2", "l6_3", "l6_4", "l6_5", "l6_6", "l6_7", "l6_8", "l6_9", "l6_10", "l6_11", "l6_12", "l6_13", "h7", "l7_1", "l7_2", "l7_3", "l7_4", "l7_5", "l7_6", "l7_7", "l7_8", "l8_1", "l8_2", "l8_3", "l8_4", "l8_5"], "lines": {"title": {"scene": "s1", "text": "JEI Korea Market Repositioning", "start": 0.6, "end": 3.11, "words": [["jei", 0.6], ["korea", 1.38], ["market", 1.66], ["repositioning", 2.12]]}, "l1_1": {"scene": "s1", "text": "Today, I will present JEI's repositioning strategy for the Korean market.", "start": 4.16, "end": 9.05, "words": [["today", 3.92], ["i", 4.72], ["will", 4.74], ["present", 4.92], ["jei's", 5.34], ["repositioning", 6.44], ["strategy", 7.3], ["for", 7.68], ["the", 8.04], ["korean", 8.14], ["market", 8.44]]}, "l1_2": {"scene": "s1", "text": "Our key message to customers is clear.", "start": 9.75, "end": 12.26, "words": [["our", 9.62], ["key", 9.98], ["message", 10.16], ["to", 10.52], ["customers", 10.78], ["is", 11.2], ["clear", 11.66]]}, "l1_3": {"scene": "s1", "text": "JEI can differentiate itself by using precise diagnosis and assessment to design the learning path each child needs, and by helping children develop the ability to grow independently.", "start": 12.96, "end": 24.25, "words": []}, "l1_4": {"scene": "s1", "text": "To deliver on that promise, we must connect our diagnostic results to each child's actual learning experience and show parents clear evidence of progress.", "start": 24.95, "end": 34.26, "words": []}, "l1_5": {"scene": "s1", "text": "I'll begin with the competitive landscape, then discuss JEI's strengths and limitations, what parents need, our proposed brand positioning, and the steps needed to deliver it.", "start": 34.96, "end": 45.09, "words": []}, "h2": {"scene": "s2", "text": "01. Korean Workbook Market and Competitive Landscape", "start": 46.54, "end": 49.82, "words": [["1", 46.41], ["korean", 47.03], ["workbook", 47.35], ["market", 47.83], ["and", 48.21], ["competitive", 48.49], ["landscape", 48.97]]}, "l2_1": {"scene": "s2", "text": "The Korean workbook market has become more competitive, with traditional providers offering increasingly different learning models.", "start": 50.62, "end": 57.62, "words": []}, "l2_2": {"scene": "s2", "text": "Competition now extends beyond workbook providers to local study rooms, private learning centers, and digital learning programs.", "start": 58.32, "end": 65.94, "words": []}, "l2_3": {"scene": "s2", "text": "The four major workbook providers in Korea have different business models and strategies.", "start": 66.64, "end": 71.73, "words": []}, "l2_4": {"scene": "s2", "text": "Daekyo operates learning spaces such as Learning Centers and Hi CAMPUS, and offers learning content through its Summit program.", "start": 72.43, "end": 79.9, "words": []}, "l2_5": {"scene": "s2", "text": "Kumon records students' handwritten work digitally and supports learning between home visits through Daily Care.", "start": 80.6, "end": 86.83, "words": []}, "l2_6": {"scene": "s2", "text": "Woongjin combines learning across all subjects with AI features through its Smart All program.", "start": 87.53, "end": 93.31, "words": []}, "l2_7": {"scene": "s2", "text": "JEI's strengths include paper-based learning, individualized learning paths, precise assessment, and instructor coaching.", "start": 94.01, "end": 101.24, "words": []}, "l2_8": {"scene": "s2", "text": "Among these competitors, Kumon is our most direct competitor because we both focus on paper-based learning and home visits.", "start": 101.94, "end": 109.25, "words": []}, "l2_9": {"scene": "s2", "text": "Therefore, JEI needs to clearly show how we design learning for each child based on assessment results.", "start": 109.95, "end": 116.16, "words": []}, "h3": {"scene": "s3", "text": "02. JEI's Strengths and Current Limitations", "start": 117.61, "end": 120.95, "words": [["2", 117.61], ["jei's", 118.47], ["strengths", 119.23], ["and", 119.61], ["current", 119.75], ["limitations", 119.99]]}, "l3_1": {"scene": "s3", "text": "JEI has five key strengths: precise diagnostic assessment, learning at each child's own pace, step-by-step workbooks, paper-based learning, and instructor coaching.", "start": 121.75, "end": 131.83, "words": []}, "l3_2": {"scene": "s3", "text": "We also have a long history and a strong reputation for quality learning materials.", "start": 132.53, "end": 137.47, "words": []}, "l3_3": {"scene": "s3", "text": "However, parents now have many learning options, including AI and digital programs.", "start": 138.17, "end": 143.19, "words": []}, "l3_4": {"scene": "s3", "text": "So, we need to give parents a clear reason to choose JEI.", "start": 143.89, "end": 147.93, "words": []}, "l3_5": {"scene": "s3", "text": "The problem we want to solve is that assessment results do not always lead to the right learning materials, starting level, or learning pace for each child.", "start": 148.63, "end": 157.58, "words": []}, "l3_6": {"scene": "s3", "text": "Even at JEI Learning Centers, if we assess students only when they first join, or only tell parents how far their child has progressed, parents may still have questions.", "start": 158.28, "end": 167.97, "words": []}, "l3_7": {"scene": "s3", "text": "Assessment results should lead to real changes in each child's learning.", "start": 168.67, "end": 173.08, "words": []}, "l3_8": {"scene": "s3", "text": "We also need to show parents how these changes help their children improve.", "start": 173.78, "end": 177.97, "words": []}, "l3_9": {"scene": "s3", "text": "Simply emphasizing self-learning, personalized learning, or AI is not enough to differentiate JEI from competitors.", "start": 178.67, "end": 186.72, "words": []}, "h4": {"scene": "s4", "text": "03. Parents' Needs and Primary Target Customers", "start": 188.17, "end": 191.34, "words": [["3", 188.02], ["parents'", 188.8], ["needs", 189.22], ["and", 189.5], ["primary", 189.78], ["target", 190.14], ["customers", 190.5]]}, "l4_1": {"scene": "s4", "text": "The first question parents ask is, \"Where is my child having difficulty, and what should my child learn first?\"", "start": 192.14, "end": 198.67, "words": []}, "l4_2": {"scene": "s4", "text": "When sharing assessment results, we should also explain which subject and level their child should start with, as well as the most appropriate learning pace.", "start": 199.37, "end": 207.73, "words": []}, "l4_3": {"scene": "s4", "text": "Parents also want their children to study independently, without constant reminders.", "start": 208.43, "end": 213.25, "words": []}, "l4_4": {"scene": "s4", "text": "Once learning begins, short assignments and instructors' encouragement help children keep studying every day.", "start": 213.95, "end": 220.31, "words": []}, "l4_5": {"scene": "s4", "text": "Over time, progress reports should show parents what their child can now do on their own and what they will learn next.", "start": 221.01, "end": 228.04, "words": []}, "l4_6": {"scene": "s4", "text": "Our first priority is parents of children in Grades 1 to 4 who want to understand where their child is having difficulty.", "start": 228.74, "end": 235.97, "words": []}, "l4_7": {"scene": "s4", "text": "For Grades 1 and 2, we focus on building regular study habits and independent learning skills.", "start": 236.67, "end": 242.49, "words": []}, "l4_8": {"scene": "s4", "text": "For Grades 2 to 4, we focus on identifying learning gaps and areas of difficulty.", "start": 243.19, "end": 248.27, "words": []}, "l4_9": {"scene": "s4", "text": "Seven-year-olds preparing for elementary school and students in Grades 5 and 6 are also important target groups.", "start": 248.97, "end": 255.75, "words": []}, "h5": {"scene": "s5", "text": "04. Core Differentiation: From Assessment to Visible Growth", "start": 257.2, "end": 261.3, "words": [["4", 257.2], ["core", 258.0], ["differentiation", 258.02], ["from", 258.56], ["assessment", 259.4], ["to", 259.88], ["visible", 260.32], ["growth", 260.68]]}, "l5_1": {"scene": "s5", "text": "Our key differentiation is not simply better grading.", "start": 262.1, "end": 265.3, "words": []}, "l5_2": {"scene": "s5", "text": "It is how we connect assessment results to individualized learning and make each child's progress visible.", "start": 266.0, "end": 272.34, "words": []}, "l5_3": {"scene": "s5", "text": "We use assessment to find where each child needs help.", "start": 273.04, "end": 276.21, "words": []}, "l5_4": {"scene": "s5", "text": "Based on the results, we select appropriate workbooks, determine the starting level, and design an individualized learning path.", "start": 276.91, "end": 284.54, "words": []}, "l5_5": {"scene": "s5", "text": "Instructors check their work, coach them where needed, and adjust their learning pace.", "start": 285.24, "end": 290.28, "words": []}, "l5_6": {"scene": "s5", "text": "Then, we assess students again and use progress reports to see what has changed and set the next learning goal.", "start": 290.98, "end": 297.3, "words": []}, "l5_7": {"scene": "s5", "text": "This is how we connect assessment, individualized learning, and instructor coaching to each child's actual progress.", "start": 298.0, "end": 305.02, "words": []}, "l5_8": {"scene": "s5", "text": "Progress reports should not simply present information in a better format.", "start": 305.72, "end": 310.03, "words": []}, "l5_9": {"scene": "s5", "text": "They should provide clear evidence of how our learning system works and how children are improving.", "start": 310.73, "end": 316.17, "words": []}, "h6": {"scene": "s6", "text": "05. Proposed Brand Positioning and Customer Messaging", "start": 317.62, "end": 320.99, "words": [["5", 317.62], ["proposed", 317.94], ["brand", 318.48], ["positioning", 318.82], ["and", 319.36], ["customer", 319.78], ["messaging", 320.18]]}, "l6_1": {"scene": "s6", "text": "JEI aims to be a brand that helps children build the ability to grow on their own through precise assessment and personalized learning paths designed for each child.", "start": 321.79, "end": 331.56, "words": []}, "l6_2": {"scene": "s6", "text": "For parents, precise assessment is a reason to choose JEI.", "start": 332.26, "end": 336.77, "words": []}, "l6_3": {"scene": "s6", "text": "The core of our service is using assessment results to choose the right learning materials and learning sequence for each child.", "start": 337.47, "end": 344.38, "words": []}, "l6_4": {"scene": "s6", "text": "Our goal is to help children understand more and solve more problems on their own.", "start": 345.08, "end": 349.86, "words": []}, "l6_5": {"scene": "s6", "text": "This is based on JEI's philosophy:", "start": 350.56, "end": 353.13, "words": []}, "l6_6": {"scene": "s6", "text": "\"We believe in the power of self-learning.\"", "start": 353.83, "end": 356.12, "words": []}, "l6_7": {"scene": "s6", "text": "Our message to customers is:", "start": 356.82, "end": 358.57, "words": []}, "l6_8": {"scene": "s6", "text": "\"What your child needs to learn. The power to learn independently.\"", "start": 359.27, "end": 363.12, "words": []}, "l6_9": {"scene": "s6", "text": "We can explain this message in one sentence:", "start": 363.82, "end": 366.36, "words": []}, "l6_10": {"scene": "s6", "text": "\"Start with a precise assessment and focus on what your child needs to learn now.\"", "start": 367.06, "end": 371.64, "words": []}, "l6_11": {"scene": "s6", "text": "In our advertising and on our website, we will show how we check each child's level and help them learn step by step in the right order.", "start": 372.34, "end": 380.11, "words": []}, "l6_12": {"scene": "s6", "text": "When meeting with parents, we will start by asking, \"What should your child learn first?\"", "start": 380.81, "end": 385.96, "words": []}, "l6_13": {"scene": "s6", "text": "Rather than simply promoting personalized learning or AI features, we need to show parents what their child needs to learn and how their child is improving.", "start": 386.66, "end": 395.47, "words": []}, "h7": {"scene": "s7", "text": "06. Service Development and Operational Directions", "start": 396.92, "end": 400.14, "words": [["6", 396.92], ["service", 397.26], ["development", 397.66], ["and", 398.16], ["operational", 398.54], ["directions", 399.24]]}, "l7_1": {"scene": "s7", "text": "We need to connect JEI's strengths in assessment and learning management across subjects.", "start": 400.94, "end": 406.29, "words": []}, "l7_2": {"scene": "s7", "text": "First, we will set clear standards for assessment and learning plans.", "start": 406.99, "end": 411.13, "words": []}, "l7_3": {"scene": "s7", "text": "Then, we will expand from Math to Korean and English.", "start": 411.58, "end": 415.04, "words": []}, "l7_4": {"scene": "s7", "text": "Second, we will connect paper-based learning and instructor coaching with digital progress reports.", "start": 415.74, "end": 421.43, "words": []}, "l7_5": {"scene": "s7", "text": "These reports should help parents track their child's progress through mobile apps and parent consultations.", "start": 422.13, "end": 428.78, "words": []}, "l7_6": {"scene": "s7", "text": "We can also explore how our Learning Centers and personalized POD workbooks could work together.", "start": 429.48, "end": 435.36, "words": []}, "l7_7": {"scene": "s7", "text": "In addition, we need to focus not only on new enrollment but also on student retention, the number of subjects per member, and revenue per customer.", "start": 436.06, "end": 444.54, "words": []}, "l7_8": {"scene": "s7", "text": "We will check our results using enrollment rates after assessment, reassessment rates, report viewing rates, and retention rates.", "start": 445.24, "end": 452.85, "words": []}, "l8_1": {"scene": "s8", "text": "In the end, parents should be able to explain how their child's learning has changed and what the next learning goal is.", "start": 454.3, "end": 461.04, "words": []}, "l8_2": {"scene": "s8", "text": "Our goal is to connect precise assessment, individualized learning, and instructor coaching, and make each child's progress visible to parents.", "start": 461.74, "end": 470.2, "words": []}, "l8_3": {"scene": "s8", "text": "This is the reason we want parents to choose JEI.", "start": 470.9, "end": 474.2, "words": []}, "l8_4": {"scene": "s8", "text": "This concludes my presentation.", "start": 474.9, "end": 476.87, "words": []}, "l8_5": {"scene": "s8", "text": "Thank you.", "start": 477.57, "end": 478.23, "words": []}}};
